diff --git a/src/main/java/hotel/reports/RatePlanReport.java b/src/main/java/hotel/reports/RatePlanReport.java
new file mode 100644
index 0000000..4677035
--- /dev/null
+++ b/src/main/java/hotel/reports/RatePlanReport.java
@@ -0,0 +1,40 @@
+package hotel.reports;
+
+import hotel.reservations.RatePlan;
+import hotel.reservations.Reservation;
+import java.math.BigDecimal;
+import java.time.YearMonth;
+import java.util.ArrayList;
+import java.util.List;
+
+/** The reservations and the money kept per rate plan, over the reservations the revenue report counts (CSV). */
+public final class RatePlanReport {
+
+    private final RevenueReport revenue;
+
+    public RatePlanReport(RevenueReport revenue) {
+        this.revenue = revenue;
+    }
+
+    public String generate(YearMonth month) {
+        List<Reservation> counted = revenue.reservationsWithRevenue(month);
+        List<String> rows = new ArrayList<>();
+        int totalReservations = 0;
+        BigDecimal totalAmount = BigDecimal.ZERO.setScale(2);
+        for (RatePlan plan : RatePlan.values()) {
+            int count = 0;
+            BigDecimal amount = BigDecimal.ZERO.setScale(2);
+            for (Reservation reservation : counted) {
+                if (reservation.ratePlan() == plan) {
+                    count++;
+                    amount = amount.add(reservation.amountKept());
+                }
+            }
+            rows.add(plan + "," + count + "," + amount.toPlainString());
+            totalReservations += count;
+            totalAmount = totalAmount.add(amount);
+        }
+        return ReportLayout.render("rate-plans", month, "rate_plan,reservations,amount", rows,
+                "total," + totalReservations + "," + totalAmount.toPlainString());
+    }
+}
diff --git a/src/main/java/hotel/reports/ReportLayout.java b/src/main/java/hotel/reports/ReportLayout.java
new file mode 100644
index 0000000..bdb6e5b
--- /dev/null
+++ b/src/main/java/hotel/reports/ReportLayout.java
@@ -0,0 +1,26 @@
+package hotel.reports;
+
+import java.util.List;
+
+/**
+ * How every CSV report is laid out: a title line (inn, report, period), the column header, the rows and
+ * the total line. A change in the look of the reports is made here, once.
+ */
+final class ReportLayout {
+
+    private static final String INN = "Pousada Maré Alta";
+
+    private ReportLayout() {
+    }
+
+    static String render(String reportName, Object period, String header, List<String> rows, String total) {
+        StringBuilder csv = new StringBuilder();
+        csv.append(INN).append(',').append(reportName).append(',').append(period).append('\n');
+        csv.append(header).append('\n');
+        for (String row : rows) {
+            csv.append(row).append('\n');
+        }
+        csv.append(total).append('\n');
+        return csv.toString();
+    }
+}
