  1	package hotel.reports;
  2	
  3	import hotel.reservations.Reservation;
  4	import hotel.reservations.ReservationStore;
  5	import java.math.BigDecimal;
  6	import java.time.YearMonth;
  7	import java.util.ArrayList;
  8	import java.util.Comparator;
  9	import java.util.List;
 10	
 11	/**
 12	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
 13	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
 14	 */
 15	public final class RevenueReport {
 16	
 17	    private final ReservationStore store;
 18	
 19	    public RevenueReport(ReservationStore store) {
 20	        this.store = store;
 21	    }
 22	
 23	    /** The reservations that count as revenue for the month, in report order. */
 24	    List<Reservation> reservationsWithRevenue(YearMonth month) {
 25	        List<Reservation> withRevenue = new ArrayList<>();
 26	        for (Reservation reservation : store.all()) {
 27	            boolean keptMoney = reservation.amountKept().signum() > 0;
 28	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
 29	            if (keptMoney && startsInMonth) {
 30	                withRevenue.add(reservation);
 31	            }
 32	        }
 33	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
 34	        return withRevenue;
 35	    }
 36	
 37	    public String generate(YearMonth month) {
 38	        List<String> rows = new ArrayList<>();
 39	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
 40	        for (Reservation reservation : reservationsWithRevenue(month)) {
 41	            rows.add(reservation.id() + "," + reservation.roomNumber() + "," + reservation.checkIn() + ","
 42	                    + reservation.checkOut() + "," + reservation.status() + ","
 43	                    + reservation.amountKept().toPlainString());
 44	            revenue = revenue.add(reservation.amountKept());
 45	        }
 46	        return ReportLayout.render("revenue", month, "reservation,room,check_in,check_out,status,amount", rows,
 47	                "total," + revenue.toPlainString());
 48	    }
 49	}
