 56	import java.time.LocalDate;
 57	import java.util.ArrayList;
 58	import java.util.Comparator;
 59	import java.util.List;
 60	
 61	/** Which rooms are occupied on a given night, for the front desk (CSV). */
 62	public final class OccupancyReport {
 63	
 64	    private final Rooms rooms;
 65	    private final ReservationStore store;
 66	
 67	    public OccupancyReport(Rooms rooms, ReservationStore store) {
 68	        this.rooms = rooms;
 69	        this.store = store;
 70	    }
 71	
 72	    public String generate(LocalDate night) {
 73	        List<Reservation> occupying = new ArrayList<>();
 74	        for (Reservation reservation : store.all()) {
 75	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
 76	            if (reservation.isPaid() && coversNight) {
 77	                occupying.add(reservation);
 78	            }
 79	        }
 80	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
 81	
 82	        List<String> rows = new ArrayList<>();
 83	        for (Reservation reservation : occupying) {
 84	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
 85	            rows.add(room.number() + "," + room.type() + "," + reservation.id() + ","
 86	                    + reservation.checkIn() + "," + reservation.checkOut());
 87	        }
 88	        String total = "total," + occupying.size() + "/" + rooms.all().size();
 89	        return ReportLayout.render("occupancy", night, "room,type,reservation,check_in,check_out", rows, total);
 90	    }
 91	}
